import{EXESNOHS_CONFIG as d}from"./config.min.js";import{standLayout as S}from"./field.min.js";import{hexToRgb as m}from"./fireworks.min.js";const F=t=>t<0?0:t>1?1:t;export const FONT={P:["####.","#...#","#...#","####.","#....","#....","#...."],E:["#####","#....","#....","####.","#....","#....","#####"],R:["####.","#...#","#...#","####.","#.#..","#..#.","#...#"],F:["#####","#....","#....","####.","#....","#....","#...."],C:[".###.","#...#","#....","#....","#....","#...#",".###."],T:["#####","..#..","..#..","..#..","..#..","..#..","..#.."],5:["#####","#....","####.","....#","....#","#...#",".###."],0:[".###.","#...#","#..##","#.#.#","##..#","#...#",".###."]},CARD_ROWS=8;export function crowdSeats(){const t=S(),s=d.milestones.finale.fans.pitch,e=Math.floor(t.totalLength/s),f=[];for(const r of[-1,1])for(let n=0;n<t.rows;n+=1)for(let o=0;o<e;o+=1)f.push({side:r,riser:n,col:o,x:t.fromX+(o+.5)*s,y:t.top(n),z:r*t.out(n)});return{seats:f,cols:e}}export function pixelMessage(t,s){const e=String(t).split("").filter(o=>FONT[o]),f=e.length?e.length*6-1:0,r=Math.floor((s-f)/2),n=new Set;return e.forEach((o,a)=>{FONT[o].forEach((h,x)=>{for(let l=0;l<h.length;l+=1)h[l]==="#"&&n.add(`${x}:${r+a*6+l}`)})}),{lit:n,width:f,left:r}}export function cardRow(t,s,e=4){return(e-1-t)*2+(s?0:1)}export function cardAt(t,s,e,f,r,{calm:n=!1}={}){const o=d.milestones.finale,a=o.cards,h=o.flip,x=(c,g)=>c[0]+g/Math.max(1,f-1)*(c[1]-c[0]-h),l=[{at:o.perfect,lit:r.perfect,on:m(a.white),off:m(a.orange)},{at:o.five,lit:r.five,on:m(a.gold),off:m(a.navy)}];let p=null,u=0;for(const c of l){const g=n?c.at[0]:x(c.at,e),i=(t-g)/h;if(i<0)break;const M=c.lit.has(`${s}:${e}`)?c.on:c.off;if(n||i>=1){p=M,u=1;continue}p?i<.5?u=Math.cos(Math.PI*i):(p=M,u=-Math.cos(Math.PI*i)):(p=M,u=Math.sin(Math.PI/2*i));break}return{turn:u,colour:p||[0,0,0]}}export function fanArrival(t,s,e,{calm:f=!1}={}){const[r,n]=d.milestones.finale.fill;if(f)return t>=r?1:0;const o=r+s.col/Math.max(1,e-1)*(n-r-.3)+s.riser*.06;return F((t-o)/.3)}
